{
  "book_code": "2ES",
  "verses": [
    {
      "text_ar": "كتاب النبي عزرا الثاني، بن سرايا، بن عزريا، بن حلقيا، بن سالوموم، بن صادوق، بن أخيتوب،",
      "chapter": 1,
      "verse": 1
    },
    {
      "text_ar": "ابن أخيا، بن فيحاس، بن عالي، بن أمريا، بن عزي، بن مريموث، بن أرنا، بن عزيا، بن بوريث، بن أبيشوع، بن فيحاس، بن ألعازار،",
      "chapter": 1,
      "verse": 2
    },
    {
      "text_ar": "ابن هارون، من سبط لاوي، الذي كان مسبياً في أرض الماديين، في ملك أتحرخششت ملك الفرس.",
      "chapter": 1,
      "verse": 3
    },
    {
      "text_ar": "فكان إلي كلام الرب قائلاً:",
      "chapter": 1,
      "verse": 4
    },
    {
      "text_ar": "اذهب وأخبر شعبي بأعمالهم الآثمة، وأولادهم بشرورهم التي صنعوها ضدي، لكي يخبروا أولاد أولادهم،",
      "chapter": 1,
      "verse": 5
    },
    {
      "text_ar": "لأن خطايا آبائهم قد زادت فيهم، لأنهم نسوني، وقدموا ذبائح لآلهة غريبة.",
      "chapter": 1,
      "verse": 6
    },
    {
      "text_ar": "ألم أخرجهم من أرض مصر، من بيت العبودية؟ لكنهم أغاضوني واحتقروا مشورتي.",
      "chapter": 1,
      "verse": 7
    },
    {
      "text_ar": "فانتف شعر رأسك والق كل الشرور عليهم، لأنهم لم يكونوا طائعين لشريعتي، بل هم شعب متمرد.",
      "chapter": 1,
      "verse": 8
    },
    {
      "text_ar": "إلى متى أحتملهم، والذين صنعت لهم خيراً كثيراً؟",
      "chapter": 1,
      "verse": 9
    },
    {
      "text_ar": "لقد أطحت بملوك كثيرين من أجلهم. وضربت فرعون مع عبيده وكل جيشه.",
      "chapter": 1,
      "verse": 10
    },
    {
      "text_ar": "وقد أهلكت كل الأمم من أمامهم. وفي المشرق، بددت شعب إقليمين، صور وصيدون، وقتلت كل أعدائهم.",
      "chapter": 1,
      "verse": 11
    },
    {
      "text_ar": "فتكلم إذن إليهم قائلاً:",
      "chapter": 1,
      "verse": 12
    },
    {
      "text_ar": "يقول الرب، حقاً لقد أجزتكم في البحر، وحيث لم يكن طريق صنعت لكم سككاً. وأعطيتكم موسى قائداً وهارون كاهناً.",
      "chapter": 1,
      "verse": 13
    },
    {
      "text_ar": "أعطيتكم نوراً في عمود نار. لقد صنعت عجائب عظيمة في وسطكم، ومع ذلك نسوتموني، يقول الرب.",
      "chapter": 1,
      "verse": 14
    },
    {
      "text_ar": "يقول الرب القدير: كانت السلوى آية لكم. وأعطيتكم مخيماً لحمايتكم، لكنكم تذممتم هناك.",
      "chapter": 1,
      "verse": 15
    },
    {
      "text_ar": "لم تفرحوا باسمي لهلاك أعدائكم، بل حتى هذا اليوم ما زلتم تتذمرون.",
      "chapter": 1,
      "verse": 16
    },
    {
      "text_ar": "أين الإحسانات التي صنعتها إليكم؟ عندما كنتم جياعاً وعطاشى في البرية، ألم تصرخوا إلي،",
      "chapter": 1,
      "verse": 17
    },
    {
      "text_ar": "قائلين: «لماذا أخلتمونا إلى هذه البرية لتميتونا؟ لكان خيراً لنا أن نخدم المصريين من أن نموت في هذه البرية».",
      "chapter": 1,
      "verse": 18
    },
    {
      "text_ar": "فأشفقت على نواحكم وأعطيتكم منا طعاماً. أكلتم خبز الملائكة.",
      "chapter": 1,
      "verse": 19
    },
    {
      "text_ar": "ولما عطستم، ألم أشق الصخرة، فخرج الماء بغزارة؟ وبسبب الحر، غطيتكم بأوراق الأشجار.",
      "chapter": 1,
      "verse": 20
    }
  ]
}
